    note:"前日の米国市場でアルファベットやマイクロソフトなど大規模クラウド事業者が牽引し、ダウ平均が最高値を更新した流れを受け、ハイテク株買いが先行してスタートした。しかし、外国為替市場で1ドル=157円台後半まで円高が進行していることや、追加の為替介入への警戒感から輸出関連株（自動車・商社）に売りが波及し、一時800円あまり下落してマイナス圏に沈む場面もあった。その後、午後に入るとAI・半導体関連やデータセンター関連銘柄の一角にリバウンド狙いの押し目買いが入り、再びプラス転換するなど、強弱材料が混在して方向感に乏しい荒い値動きとなった。この日は93社が決算発表を行う決算集中日で、三菱重工業・日本製鉄・クボタなど大型株の好決算が相次いだ一方、トヨタ自動車は1Q最終減益、横河電機も大幅減益となった。"
