      detail:"8/13昼（11:30）に決算を発表。26年12月期第2四半期累計（1-6月）の連結最終利益は前年同期比29.2%増の101億円に伸びた。あわせて通期の同利益を従来予想の195億円→205億円（前期は167億円）に5.1%上方修正し、増益率を16.4%増→22.4%増に拡大、従来10期ぶりとしていた過去最高益予想をさらに上乗せした。上期実績と通期計画から試算すると、7-12月期（下期）の最終利益は前年同期比16.4%増の103億円に伸びる計算になる。業績好調に伴い、年間配当予想を従来計画の26円→27円（前期は22円）に増額修正した。4-6月期（2Q）単独の最終利益は前年同期比31.9%増の46.5億円、売上営業利益率は前年同期の5.8%→6.6%に改善した。株価は+1.72%（3,255.0円）で引けた。",
      outlook:"10期ぶり最高益予想のさらなる上振れ余地と、既存店売上高の動向が今後の材料。下期試算（前年比16.4%増）の達成確度にも注目したい。"
